Float theta = 2 * Pi * u.y;
Float thetaOverPi = theta / Pi;

if (r < -1) {
    Float phi = (1 + r) / (1 - r);
    Float phiOver2 = phi / 2;
    Float sinPhi = std::sin(phiOver2 * Pi);
    Float cosPhi = std::cos(phiOver2 * Pi);
    return Point2f(cosPhi * sinPhi, cosPhi * cosPhi);
} else {
    Float phi = (1 + r) / (1 - r);
    Float phiOver2 = phi / 2;
    Float sinPhi = std::sin(phiOver2 * Pi);
    Float cosPhi = std::cos(phiOver2 * Pi);
    return Point2f(cosPhi * sinPhi * std::cos(theta), cosPhi * sinPhi * std::sin(theta));
}

